{
  "ferramenta": "image_gen integrada",
  "direcao": "Qualidade da pose de transporte aprovada pelo usuário em 23/10/2026; aplicar a todas as poses 2D da menina.",
  "referencia": "assets/art/toy-room/stage2/carry-v2/poses.png",
  "pranchas": [
    {
      "key": "locomocao",
      "prompt": "Use case: identity-preserve. Production sprite atlas for a 2D game. The reference is the NEW APPROVED character and visual-quality standard. Preserve exactly this little girl's face, brown eyes, brown pigtails and pink bows, toddler proportions, cream dress with pink trim and embroidery, brown boots. Same detailed outlined hand-painted storybook sprite rendering and texture. NO crude enlarged pixels, NO photorealism, NO 3D. All sprites full body, face RIGHT three-quarter side view, equal scale and consistent head size, lit from upper left. Genuine transparent alpha, generous transparent space around each cell. No floor, ground shadow, props unless specifically requested, labels, text or grid dividers. Layout exactly FOUR columns by TWO rows, eight equal cells, read left to right then top to bottom. Keep all body parts inside their own cell. Frames 1 and 2: neutral standing idle, hands relaxed down at sides (NOT holding anything); slight breathing variation only. Frames 3 to 8: SIX clearly DISTINCT sequential natural running-cycle keyframes with alternating left/right leg support, opposite arm swing, including both passing poses. No bent carrying arms! Hair and skirt follow motion. Same fixed ground baseline, same character proportions across all frames."
    },
    {
      "key": "saltos",
      "prompt": "Use case: identity-preserve. Production sprite atlas for a 2D game. The reference is the NEW APPROVED character and visual-quality standard. Preserve exactly this little girl's face, brown eyes, brown pigtails and pink bows, toddler proportions, cream dress with pink trim and embroidery, brown boots. Same detailed outlined hand-painted storybook sprite rendering and texture. NO crude enlarged pixels, NO photorealism, NO 3D. All sprites full body, face RIGHT three-quarter side view, equal scale and consistent head size, lit from upper left. Genuine transparent alpha, generous transparent space around each cell. No floor, ground shadow, props unless specifically requested, labels, text or grid dividers. Layout exactly FOUR columns by TWO rows, eight equal cells, read left to right then top to bottom. Keep all body parts inside their own cell. Eight distinct action poses. 1: jump takeoff, knees extending, arms helping lift. 2: rising airborne, knees slightly bent. 3: high jump apex, legs tucked naturally. 4: early descending, hands balancing. 5: falling, legs extending toward landing. 6: landing anticipation, bent knees, feet ready. 7: fast forward DASH, body leaned forward with strong running stride, NO motion trails. 8: deep crouch with bent knees and lowered torso, head remains SAME SIZE as other frames; do NOT shrink the whole girl. No sword, no toy."
    },
    {
      "key": "acoes",
      "prompt": "Use case: identity-preserve. Production sprite atlas for a 2D game. The reference is the NEW APPROVED character and visual-quality standard. Preserve exactly this little girl's face, brown eyes, brown pigtails and pink bows, toddler proportions, cream dress with pink trim and embroidery, brown boots. Same detailed outlined hand-painted storybook sprite rendering and texture. NO crude enlarged pixels, NO photorealism, NO 3D. All sprites full body, face RIGHT three-quarter side view, equal scale and consistent head size, lit from upper left. Genuine transparent alpha, generous transparent space around each cell. No floor, ground shadow, props unless specifically requested, labels, text or grid dividers. Layout exactly FOUR columns by TWO rows, eight equal cells, read left to right then top to bottom. Keep all body parts inside their own cell. Eight distinct full-body game poses. 1: happy collecting, both hands raised above head, smiling. 2: pushing to the RIGHT with both arms extended at waist level, torso leaning forward, feet braced, no object drawn. 3: climbing, one knee lifted and both hands reaching upward, no ladder. 4: interacting, one hand reaching forward at chest level. 5: lying on her side sleeping, horizontal body, eyes closed, no bed/pillow. 6: teleport anticipation, both arms open palms up, looking amazed, no portal drawn. 7: teleport completion, arms lowered, upright calm. 8: recoiling from a hit, one hand protecting torso, knees bent, surprised expression. Preserve the exact same head scale even in lying/climbing poses."
    }
  ]
}
